import React from 'react'
import ReactDOM from 'react-dom/client'
import App from './App'
import Services from './pages/Services'
import InvestFinanceValue from './pages/InvestFinanceValue'
import PlanLeaseOccupy from './pages/PlanLeaseOccupy'
import DesignBuild from './pages/DesignBuild'
import './index.css'

const path = window.location.pathname;

let Component = App;

if (path.includes('services-invest-finance-value')) {
  Component = InvestFinanceValue;
} else if (path.includes('services-plan-lease-occupy')) {
  Component = PlanLeaseOccupy;
} else if (path.includes('services-design-build')) {
  Component = DesignBuild;
} else if (path.includes('services')) {
  Component = Services;
}

ReactDOM.createRoot(document.getElementById('app')!).render(
  <React.StrictMode>
    <Component />
  </React.StrictMode>,
)
EOF

